/* Level 07 (Umbris) code following partupd; generated by tools/overlay_src.py, stubs replaced by C as functions are
   matched. Starts at 0x0029D2B8 (was partupd_0029D2B8.c). */
#include "common.h"
#include "callees.h"
#include "include_asm.h"
#include "overlays/shared/moby_ground_collision.h"
#include "game/math/fastfunc.h"
#include "game/moby/mobyutil.h"
#include "asm_functions/executable.h"

extern int truncate_float_to_s32(float);

extern unsigned char *umbris_part_type65_textures;

/* Spawn a particle moby at pos with a colour, lifetime and size. */
void spawn_white_particle_with_payload(void *pos, void *pos2) {
    unsigned char *p = create_part(0x41);
    if (p) {
        float *f = (float *)(p + 0x20);
        qcopy(p + 0x10, pos);
        *(int *)(p + 4) = PackColorRGBA(1.0f, 1.0f, 1.0f, 0.6f);
        p[9] = truncate_float_to_s32(4.0f) + 0x40;
        p[1] = 0;
        p[3] = 0x48;
        *(float *)(p + 0xC) = random_float_between(20000.0f, 120000.0f);
        p[8] = 0;
        p[2] = *umbris_part_type65_textures;
        f[4] = 1.0f;
        f[5] = 1.0f;
        f[6] = 1.0f;
        f[7] = 0.6f;
        *(short *)(p + 0xA) = scale_ticks(0x50);
        qcopy(f, pos2);
    }
}

typedef int u128 __attribute__((mode(TI)));

/* Clamped closest-approach point of a moving sphere on level 7; writes the point to dst, returns its distance term. */
float select_segment_point_near_sphere_surface(char *dst, char *a1, char *a2, char *a3, char *a4, float f) {
    u128 v[5];
    u128 *q4;
    float r1, r2, r3, t20, lo, hi, L, d, f21, t22, thr, ap;

    FastVecSub(v + 0, a3, a2);
    FastVecSub(v + 1, a4, a3);
    L = FastVecDot(v + 1, v + 1);
    d = FastVecDot(v + 0, v + 1);
    f21 = -d / L;
    FastVecScale(v + 2, v + 1, f21);
    FastVecAdd(v + 2, v + 2, a3);
    r1 = fast_vec_dist(v + 2, a2);
    if (r1 < f) {
        ap = f * f - r1 * r1;
        t20 = square_root(ap);
        t20 = t20 / FastVecLength(v + 1);
        lo = f21 - t20;
        if (lo < 0)
            lo = 0;
        else if (lo > 1)
            lo = 1;
        hi = f21 + t20;
        if (hi < 0)
            hi = 0;
        else if (hi > 1)
            hi = 1;
        FastVecScale(v + 3, v + 1, lo);
        FastVecAdd(v + 3, v + 3, a3);
        r2 = fast_vec_dist(v + 3, a2);
        t22 = absolute_float(r2 - f);
        thr = f * 0.01f;
        if (t22 < thr)
            t22 = 0;
        q4 = v + 4;
        FastVecScale(q4, v + 1, hi);
        FastVecAdd(q4, q4, a3);
        r3 = fast_vec_dist(q4, a2);
        f21 = absolute_float(r3 - f);
        if (f21 < thr)
            f21 = 0;
        if (t22 < f21 || (t22 == f21 && fast_vec_dist(v + 3, a1) < fast_vec_dist(q4, a1))) {
            qcopy(dst, v + 3);
            r1 = t22;
        } else {
            qcopy(dst, q4);
            r1 = f21;
        }
    } else {
        if (f21 < 0) {
            qcopy(dst, a3);
            r1 = absolute_float(fast_vec_dist(dst, a2) - f);
        } else if (1.0f < f21) {
            qcopy(dst, a4);
            r1 = absolute_float(fast_vec_dist(dst, a2) - f);
        } else {
            qcopy(dst, v + 2);
        }
        if (r1 < f * 0.01f)
            r1 = 0;
    }
    return r1;
}
